"""Handle position endpoints for MT4 (replaces OANDA)."""

from .apirequest import APIRequest
from .decorators import dyndoc_insert, endpoint
from .responses.positions import responses
from abc import abstractmethod


class Positions(APIRequest):
    """Positions - abstractbase class to handle the 'positions' endpoints for MT4."""

    ENDPOINT = ""
    METHOD = "GET"

    @abstractmethod
    @dyndoc_insert(responses)
    def __init__(self, accountID, instrument=None):
        """Instantiate a Positions APIRequest instance for MT4.

        Parameters
        ----------
        accountID : string (required)
            the id of the account to perform the request on.

        instrument : string (optional)
            the instrument for the Positions request

        """
        endpoint = self.ENDPOINT.format(accountID=accountID,
                                        instrument=instrument)
        super(Positions, self).__init__(endpoint,
                                        method=self.METHOD)


@endpoint("v3/accounts/{accountID}/positions")
class PositionList(Positions):
    """PositionList for MT4.

    List all Positions for an Account. The Positions returned are for every
    instrument that has had a position during the lifetime of the Account.
    For MT4, this retrieves open positions from the terminal.
    """

    @dyndoc_insert(responses)
    def __init__(self, accountID):
        """Instantiate a PositionList request for MT4.

        Parameters
        ----------
        accountID : string (required)
            id of the account to perform the request on.

        For MT4, this retrieves positions via the file bridge.
        """
        super(PositionList, self).__init__(accountID)


@endpoint("v3/accounts/{accountID}/openPositions")
class OpenPositions(Positions):
    """OpenPositions for MT4.

    List all open Positions for an Account. An open Position is a Position
    in an Account that currently has a Trade opened for it.
    
    For MT4, this returns currently open positions from the terminal.
    """

    @dyndoc_insert(responses)
    def __init__(self, accountID):
        """Instantiate an OpenPositions request for MT4.

        Parameters
        ----------
        accountID : string (required)
            id of the account to perform the request on.

        For MT4, this retrieves open positions via the file bridge.
        """
        super(OpenPositions, self).__init__(accountID)


@endpoint("v3/accounts/{accountID}/positions/{instrument}")
class PositionDetails(Positions):
    """PositionDetails for MT4.

    Get the details of a single instrument's position in an Account. The
    position may be open or not.
    """

    @dyndoc_insert(responses)
    def __init__(self, accountID, instrument):
        """Instantiate a PositionDetails request for MT4.

        Parameters
        ----------
        accountID : string (required)
            id of the account to perform the request on.

        instrument : string (required)
            id of the instrument to get the position details for.

        For MT4, this retrieves position details from the terminal.
        """
        super(PositionDetails, self).__init__(accountID, instrument)


@endpoint("v3/accounts/{accountID}/positions/{instrument}/close", "PUT")
class PositionClose(Positions):
    """Closeout the open Position regarding instrument in an Account for MT4.

    For MT4, this closes an open position via the file bridge.
    """

    HEADERS = {"Content-Type": "application/json"}

    @dyndoc_insert(responses)
    def __init__(self, accountID, instrument, data):
        """Instantiate a PositionClose request for MT4.

        Parameters
        ----------
        accountID : string (required)
            id of the account to perform the request on.

        instrument : string (required)
            instrument to close partially or fully.

        data : dict (required)
            closeout specification data to send.

        For MT4, this sends a close position command via the file bridge.
        """
        super(PositionClose, self).__init__(accountID, instrument)
        self.data = data


# ============ MT4 Position Helper Functions ============

class MT4PositionManager:
    """
    MT4 Position Manager - replaces OANDA position endpoints functionality
    Uses the MT4 file bridge to get and manage positions.
    """
    
    def __init__(self):
        from mt4_price_provider import get_mt4_prices
        self.mt4 = get_mt4_prices()
    
    def get_all_positions(self):
        """
        Get all positions from MT4 (replaces PositionList)
        
        Returns:
            list: List of open positions with ticket, symbol, type, volume, etc.
        """
        try:
            result = self.mt4.get_positions()
            if result.get('success'):
                return result.get('positions', [])
            return []
        except Exception as e:
            print(f"Error getting positions: {e}")
            return []
    
    def get_open_positions(self):
        """
        Get all open positions (replaces OpenPositions)
        
        Returns:
            list: List of currently open positions
        """
        return self.get_all_positions()
    
    def get_position_details(self, instrument):
        """
        Get position details for a specific instrument (replaces PositionDetails)
        
        Parameters:
        -----------
        instrument : str
            Instrument symbol (e.g., 'EURUSD')
        
        Returns:
            dict: Position details or None if not found
        """
        positions = self.get_all_positions()
        for pos in positions:
            if pos.get('symbol') == instrument:
                return pos
        return None
    
    def close_position(self, ticket):
        """
        Close a specific position by ticket number (replaces PositionClose)
        
        Parameters:
        -----------
        ticket : int
            MT4 ticket number of the position to close
        
        Returns:
            dict: Result of the close operation
        """
        try:
            result = self.mt4.close_position(ticket)
            return result
        except Exception as e:
            return {'success': False, 'error': str(e)}
    
    def close_position_by_instrument(self, instrument):
        """
        Close position by instrument symbol
        
        Parameters:
        -----------
        instrument : str
            Instrument symbol to close
        
        Returns:
            dict: Result of the close operation
        """
        position = self.get_position_details(instrument)
        if position:
            return self.close_position(position.get('ticket'))
        return {'success': False, 'error': f'No open position for {instrument}'}
    
    def get_positions_summary(self):
        """
        Get summary of all positions
        
        Returns:
            dict: Summary with total positions, total volume, total profit
        """
        positions = self.get_all_positions()
        
        summary = {
            'total_positions': len(positions),
            'total_volume': sum(p.get('volume', 0) for p in positions),
            'total_profit': sum(p.get('profit', 0) for p in positions),
            'buy_positions': sum(1 for p in positions if p.get('type') == 'BUY'),
            'sell_positions': sum(1 for p in positions if p.get('type') == 'SELL'),
            'positions': positions
        }
        
        return summary


# ============ Global instance ============

_mt4_position_manager = None

def get_position_manager():
    """Get the global MT4 position manager instance"""
    global _mt4_position_manager
    if _mt4_position_manager is None:
        _mt4_position_manager = MT4PositionManager()
    return _mt4_position_manager
